VALID_DIFFICULTIES = {"easy", "medium", "hard"}


def normalise_difficulty_and_totals(apps, schema_editor):
    """ASM-04: map free-text difficulty onto the choices and resync total_marks.

    Existing quizzes keep their is_published value; only new quizzes default
    to draft.
    """
    Quiz = apps.get_model("assessments", "Quiz")
    QuizQuestion = apps.get_model("assessments", "QuizQuestion")
    for question in QuizQuestion.objects.exclude(difficulty__in=VALID_DIFFICULTIES).only("difficulty"):
        value = (question.difficulty or "").strip().lower()
        question.difficulty = value if value in VALID_DIFFICULTIES else "medium"
        question.save(update_fields=["difficulty"])
    for quiz in Quiz.objects.annotate(sum_marks=Sum("questions__marks")):
        total = quiz.sum_marks or 0
        if quiz.total_marks != total:
            Quiz.objects.filter(pk=quiz.pk).update(total_marks=total)


